import java.util.*;

class Solution {
    public boolean sameCounts(String s, String t) {
        Map<Character, Integer> sc = new HashMap<>();
        Map<Character, Integer> tc = new HashMap<>();
        for (char c : s.toCharArray()) sc.put(c, sc.getOrDefault(c, 0) + 1);
        for (char c : t.toCharArray()) tc.put(c, tc.getOrDefault(c, 0) + 1);
        if (sc.size() != tc.size()) return false;
        for (char c : sc.keySet()) {
            if (!sc.get(c).equals(tc.get(c))) return false;
        }
        return true;
    }
}
